function setCollapsedPanel(obj,e) {			
	if ($(obj).parents('.panel').children('.panel-collapse').hasClass('in')){
		return false;
	}
	$('.panel-heading').removeClass('active');
	$('.nav-tabs.hidden-xs li').removeClass('active');
	$('.tab-pane').removeClass('active');

	if (!$(obj).hasClass("collapsed")) { //closed			
		$(obj).prev('.fa').removeClass("fa-angle-up").addClass("fa-angle-down");
	} else { // open
		$(obj).parents('.panel-heading').addClass('active');
		var thisIndex = $('.panel-heading.active').closest('.panel').index();
		$('.nav-tabs.hidden-xs li').eq(thisIndex).addClass('active');
		$('.tab-pane').eq(thisIndex).addClass('active');
		$(obj).prev('.fa').removeClass("fa-angle-down").addClass("fa-angle-up");
	}
}




