	function viewMiniCart() {
		
			if ( typeof(vmcAjax) == "object" ) { // prevent multiple calls
				vmcAjax.abort();
			}
			
			//var thisUrl = "/cart.txt?action=view";
			 var thisUrl = "/cart/getMiniCartAjax";
			vmcAjax = $.getJSON(thisUrl)
			.done(function(data) {
				//console.log(data[0]["result"]);

				if (data.success == 1) {	
					
					$("#minicart-txt").text(data.count);
					/*
					if (data.count == 0) {
						$("#signup-link").addClass("hide");
					} else {
						$("#signup-link").removeClass("hide");
					}
					*/
					updateSignupLink(data.count);
					$("#minicart_container").html(data.miniCartHtml).removeClass("hide");
					renderMiniCart();
					
				}
				
			})
			.fail(function() {
				console.log("error viewing cart");
			})


	}


