function cartCheckout() {
	
	if ($("#rica-drop-container").length == 1 && ricaFilesUploaded != 2) {
		$("#signup-4 .moverlay-content").velocity("callout.shake");
		$("#signin-overlay").scrollTop(700);
		$('#btn-signup-4').removeClass("success").removeAttr("disabled");
		$('#rica-drop-container').find(".errmsg1").removeClass("hide").html("Rica uploads are required");
		return;
	}
	

	$('#btn-signup-4').attr("disabled","disabled").addClass("success").afterTime(500, function () {
			var thisData = "";
			if ($("input[name='paymenttype']").length != 0) {
				thisData = "paymenttype="+$("input[name='paymenttype']:checked").val();
			}
			if ($("#frm-ccbudget").length == 1) {
				thisData += "&"+$("#frm-ccbudget").serialize();
			} else {
				thisData += "";
			}

			if ( typeof(signupAjax) == "object" ) { // prevent multiple calls
				signupAjax.abort();
			}

			signupAjax = $.ajax({
				method: "POST",
				url: "/cart/checkout",
				timeout: 25000,
				cache: false,
				dataType: "json",
				data: thisData
			})
			.done(function(data) {

				$('#btn-signup-4').removeClass("success disabled").removeAttr("disabled");
				$('#signup-4').find(".errmsg").addClass("hide");
				
				if (data.success == 1) { //success
				
					if (data.contentHtml != undefined) {
					
						$("#signup-5").html(data.contentHtml);
						iniSelectPicker();
						var index = 4;
						var activeStep = index-1;
						//$(".step").find(".step-status:eq("+activeStep+")").addClass("complete");
						$(".step").find(".step-status:eq("+activeStep+")").html('<i class="fa fa-check"></i>');					
						if ($(".step").find(".step-status:eq("+(activeStep+1)+")").length != 0) {
							$(".step").find(".step-status:eq("+(activeStep+1)+")").addClass("pointer");
						}
						signupWizard('',index+1);	
						
					} else if (data.postfrm != undefined) {
						/*
						$("#frm-redirect").remove();
						var redirectForm = $(data.postfrm);
						$("body").append(redirectForm);
						redirectForm.attr("id","frm-redirect");
						$("#frm-redirect").submit();
						*/
						//transitionPage(data.postUrl,'link');
					
						$("#frm-redirect").remove();
						var redirectForm = $(data.postfrm);			
						$("body").append(redirectForm);
						redirectForm.attr("id","frm-redirect");
						if (isMobile) {
							var mobileVal = "Y";
						} else {
							var mobileVal = "N";
						}
						redirectForm.find("[name='Mobile']").val(mobileVal);
						$("#frm-redirect").submit();
					
					} else if (data.postUrl != undefined) {

                        transitionPage(data.postUrl,'link');
                    }


				} else {
					// failure
					$("#signup-4 .moverlay-content").velocity("callout.shake");
				//$('#btn-signup-4').removeClass("success").removeAttr("disabled");
					//$('#signup-4-header').find(".errmsg").removeClass("hide").html(data.error);
					$("#signin-overlay").scrollTop(0);
					$("#signin-container").scrollTop(0);
					$('#signup-4-header').find(".errmsg").removeClass("hide").html(data.error).afterTime(4500, function () {
						if (data.postUrl != undefined) {
							transitionPage(data.postUrl+'user/payment-method','link');
						}
					});	
                    
				}
			
			})
			.fail(function(xhr, status, error) {
                    var err = JSON.parse(xhr.responseText);
					console.log('error on checkout');
					$("#signup-4 .moverlay-content").velocity("callout.shake");
					$('#btn-signup-4').removeClass("success").removeAttr("disabled");
					$('#signup-4-header').find(".errmsg").removeClass("hide").html(err.error);
			})	
			
		});	
			


}




