	function debounce(func, wait, immediate) {
	  var timeout;

	  return function() {
		var context = this;
		var args = arguments;

		var later = function() {
		  timeout = null;
		  if (!immediate) func.apply(context, args);
		};

		var callNow = immediate && !timeout;
		clearTimeout(timeout);
		timeout = setTimeout(later, wait);

		if (callNow) func.apply(context, args);
	  };
	};	

	
	
	function autoCompleteSource(query, syncResults, asyncResults, provider) {
	
		// remove whitespace
		var query = query.replace(/^\s+|\s+$/g,"");
	
		// check for lat,lng
		if (/^[-+]?([1-8]?\d(\.\d+)?|90(\.0+)?),\s*[-+]?(180(\.0+)?|((1[0-7]\d)|([1-9]?\d))(\.\d+)?)$/.test(query)) {
		
			if (provider == "location") { // lat,lng matched
				latlngSource(query, syncResults, asyncResults);
			}
		
		} else { // only look up google/openserve suggestions if it doesnt match valid latlng

			if (provider == "google") {
				googleSource(query, syncResults, asyncResults);
			}
			
			if (provider == "openserve") {
				openserveSource(query, syncResults, asyncResults);
			}
		
		}

	
	}
	
	
	
	var googleSource = debounce(function(query, syncResults, asyncResults){

		//var googleAutoService = new google.maps.places.AutocompleteService();

		googleAutoService.getPlacePredictions({
			input: query,
			componentRestrictions: {country: 'za'},
			types: ["address"],
			//sessionToken:sessionToken
		}, function(predictions, status) {
			if (status == google.maps.places.PlacesServiceStatus.OK) {
				googleAddresses = [];
				predictions.forEach(function(prediction) {
					googleAddresses.push(prediction.description);
				});
				asyncResults(predictions);
			}
		});

	},900);	
	
	var openserveSource = debounce(function(query, syncResults, asyncResults){	
		$.get( '/openserve-calls/get-openserve-suggestions-ajax', { text: query }, function ( data ) {
			asyncResults(JSON.parse(data));
		} );
	},200);	
	
	var latlngSource = debounce(function(query, syncResults, asyncResults){	
		var data = [{latlng: query}];
		asyncResults(data);	
	},200);		
	

	
	
	async function initAutocompleteAddress() {
		
		const {AutocompleteService} = await google.maps.importLibrary("places");
		
		//googleAutoService = new google.maps.places.AutocompleteService();
		googleAutoService = new AutocompleteService();

		// remove duplicate suggestions
		var suggestionFilter = function(suggestions) {
			return $.grep(suggestions, function(suggestion) {
				if (typeof googleAddresses != "undefined") {
					return $.inArray(suggestion.name, googleAddresses) === -1;
				} else {
					return true;
				}
			});
		}
	
	}	
	
	
