	$('#addresssearch-autocomplete').bind('typeahead:selected', function (ev, suggestion) {	

		$(".loader").remove();
		$("#addresssearch-container .row").prepend('<div class="loader"><div class="loader-text">Please be patient while we check your address for multiple services</div><i class="fa fa-refresh fa-spin"></i></div>');
		$("#addresssearch-status .col-xs-12").html("");
		$("#addresssearch-status").removeClass("success error").addClass("hide").removeAttr('style');
		$("#addresssearch-content").html("");
		$("#addresssearch-mapimg").html("");				
		
		initDummyMap();

		if (suggestion.place_id != undefined) {	

			// google suggestion
			var geocoderNew = new google.maps.Geocoder();
			geocoderNew.geocode({placeId: suggestion.place_id}, function(results, status) {
				if (status === google.maps.GeocoderStatus.OK) {
				
					var geoIndex = precisionIndex(results);
					if (results[geoIndex]) {
						dummyMap.setCenter(results[geoIndex].geometry.location);
						dummyMap.setZoom(17);
						var place = placeToStr(results[geoIndex]);
						checkInternet(results[geoIndex].geometry.location,results[geoIndex].formatted_address,dummyMap,place);
					}
				}
			});			
			

		} else {
			
			// latlng exists
			if (suggestion.latlng != undefined) {
				
				var latLng = suggestion.latlng.split(",");					
				var latLngObj = new google.maps.LatLng(parseFloat(latLng[0]), parseFloat(latLng[1]));

				var geocoderNew = new google.maps.Geocoder();
				geocoderNew.geocode({'location': latLngObj}, function(results, status) {
					if (status === google.maps.GeocoderStatus.OK) {
													
						var geoIndex = precisionIndex(results);
						if (results[geoIndex]) {
							dummyMap.setCenter(results[geoIndex].geometry.location);
							dummyMap.setZoom(17);
							var place = placeToStr(results[geoIndex]);
							checkInternet(results[geoIndex].geometry.location,results[geoIndex].formatted_address,dummyMap,place);
						}
						
					}
				});	
				
			} else {
			
				// openserve suggestion
				if ( typeof(openserveLatLonAjax) == "object" ) { // prevent multiple calls
					openserveLatLonAjax.abort();
				}	
				openserveLatLonAjax = $.ajax({
					method: "GET",
					url: "/openserve-calls/get-openserve-address-lat-lon-ajax?address="+suggestion.name,
					timeout: 25000,
					cache: false,
					dataType: "json"
				})
				.done(function(data) {	
							
					if (data.success == 1) {
						
						var latLng = data.LatLng.split(",");					
						var latLngObj = new google.maps.LatLng(parseFloat(latLng[0]), parseFloat(latLng[1]));

						var geocoderNew = new google.maps.Geocoder();
						geocoderNew.geocode({'location': latLngObj}, function(results, status) {
							if (status === google.maps.GeocoderStatus.OK) {
															
								var geoIndex = precisionIndex(results);
								if (results[geoIndex]) {
									dummyMap.setCenter(results[geoIndex].geometry.location);
									dummyMap.setZoom(17);
									var place = placeToStr(results[geoIndex]);
									checkInternet(results[geoIndex].geometry.location,results[geoIndex].formatted_address,dummyMap,place);
								}
								
							}
						});				
			
					} else if (data.success == 0) {	
						$(".openserve-result-alert").addClass("in").afterTime(4500, function () {
							$(".openserve-result-alert").removeClass("in");
						});
						$(".loader").remove();
					}		
					
				})
				.fail(function() {
					console.log("error on getting lat lon");
					$(".openserve-result-alert").addClass("in").afterTime(4500, function () {
						$(".openserve-result-alert").removeClass("in");
					});
					$(".loader").remove();
				})		

			
			}
			
			
		}
				

	});
	


	function precisionIndex(results,latlng) {
		var precisionIndex = 0;
		if (results.length > 1) {
			for (var i=0; i < results.length; i++) {
				if (results[i].geometry.location_type == "ROOFTOP") {
					precisionIndex = i;
					break;
				}
			}
		}
		return precisionIndex;
	}
	



	function updateObject(object, path, newValue){
		var stack = path.split('>');
		while(stack.length>1){
			object = object[stack.shift()];
		}
		object[stack.shift()] = newValue;
	}
	
	function checkNoticeObject(cat) {
		var thisCatVal = noticeStatus[cat];
		if (thisCatVal != 0) {
			var thisSelectVal = $("select.select-filter-networkarea:visible option:selected").val();
			if (thisSelectVal == thisCatVal) {
				return false;
			}
		}
		
		return true;	
	}
	

	function updateNotices(cat,filter,type) {
		if ( typeof(updateNoticesAjax) == "object" ) { // prevent multiple calls
			updateNoticesAjax.abort();
		}	
	
	
		//if (checkNoticeObject(cat)) { // only do call if network area changes
	
			$("#netstatus-container-"+cat).find(".netstatus-content-container").prepend('<div class="product-loader"><i class="fa fa-refresh fa-spin"></i></div>');
	
			var thisUrl = "/support/notices-network-area-ajax?type="+type+"&filter="+filter;
			updateNoticesAjax = $.getJSON(thisUrl)
			.done(function(data) {

				$(".product-loader").remove();
			
				if (data.success == 1) {
				
					$("#netstatus-link").html(data.status);
					//$(".netlink[data-netstatustype="+cat+"]").html(data.categories);
					//$("#netlink-"+cat).html(data.categories);
					$("#netstatus-container-"+cat).find(".netstatus-content-container").html(data.result);
					
					updateObject(noticeStatus, cat, filter);	

				}
				
			})
			.fail(function() {
				$(".product-loader").remove();
				console.log("error updating network notices");
			})
		
		//}
	}

	
