	function removeTr69(obj) {
	
		var $thisFrm = $(obj).closest("form");
		var thisKey = $thisFrm.find("input[name=key]").val();
	
		if ( typeof(tr69ClearAjax) == "object" ) { // prevent multiple calls
			tr69ClearAjax.abort();
		}

		tr69ClearAjax = $.ajax({
			method: "POST",
			url: "/cart/remove-router-wifi-details/"+thisKey,
			timeout: 25000,
			cache: false,
			dataType: "json"
		})
		.done(function(data) {
		
			if (data.success == 1) { //success
			
				$thisFrm.find("input[name=tr69ssid]").val("");
				$thisFrm.find("input[name=tr69wpa]").val("");
				
				$thisFrm.find(".tr69-container").removeClass("hide");	
				$thisFrm.data("formValidation").resetForm();
				$thisFrm.find(".tr69-container").addClass("hide");	
			
				$(obj).removeAttr("data-active");
			}
			
		})
		.fail(function() {
			console.log("error on clearing WiFI details");
		})	
	
	}


	function setTr69(obj) {

		var $thisFrm = $(obj).closest("form");
		$thisFrm.find(".tr69-row").addClass("active");
		$thisFrm.find(".tr69-container").removeClass("hide");
		
		var fv = $thisFrm.data('formValidation');
		if (!fv) {			
		
			$thisFrm.find(".wpakey-eye").on("click", function(){
				if ($(this).find("span").hasClass('glyphicon-eye-close')){
					$(this).find("span").removeClass('glyphicon-eye-close').addClass('glyphicon-eye-open');
					$thisFrm.find("input[name=tr69wpa]").attr('type','text');
				} else {
					$(this).find("span").removeClass('glyphicon-eye-open').addClass('glyphicon-eye-close');
					$thisFrm.find("input[name=tr69wpa]").attr('type','password');					
				}
			});
		
			$thisFrm.formValidation({
				framework: 'bootstrap',
				excluded: [':disabled', ':hidden', ':not(:visible)'],
				icon: {
					valid: 'fa fa-check',
					invalid: 'fa fa-close',
					validating: 'fa fa-refresh'
				},
				fields: {
					tr69ssid: {
						validators: {
							notEmpty: {
								message: 'SSID is a Required Field'
							},
							regexp: {
								regexp: /^(?!.*[!#;])[\w\-]{3,32}$/,
								message: 'SSID is invalid (Max 32 chars. Cannot start with !#; The +]/ chars are invalid)'
							}
						}
					},
					tr69wpa: {
						validators: {
							notEmpty: {
								message: 'WPA Key is a Required Field'
							},
							regexp: {
								regexp: /^[\u0020-\u007e]{8,63}$/,
								message: 'WPA Key is invalid (min 8 chars)'
							}
						}
					}		
				}
			}).on('success.form.fv', function(e, data) {
				e.preventDefault();
				var frm = $(e.target);
					
				if ( typeof(tr69PostAjax) == "object" ) { // prevent multiple calls
					tr69PostAjax.abort();
				}

				tr69PostAjax = $.ajax({
					method: "POST",
					url: "/cart/set-router-wifi-details/",
					timeout: 25000,
					cache: false,
					data: frm.serialize(),
					dataType: "json"
				})
				.done(function(data) {
				
					frm.find(".btn[type=submit]").removeClass("success disabled").removeAttr("disabled");
					
					if (data.success == 1) { //success
						
						// show status
						frm.find(".tr69-container .row-status").remove();
						frm.find(".tr69-container").prepend('<div class="row row-status">Details have been successfully updated</div>');
						
						//clear status
						setTimeout(function(){
							frm.find(".tr69-container .row-status").remove();	
						}, 3500);
						
						$(obj).attr("data-active","true");
						
					} else if (data.success == 0) {
						frm.find(".tr69-row.active").velocity("callout.shake");
						frm.data("formValidation").resetForm();
					}
					
				})
				.fail(function() {
					console.log("error on updating WiFI details");
				})
			})
				
		}	
	
	}

	
	
