	var preventClick = false;
	var isMouseDown = false;

	// close overlay when overlay background is clicked

	/*if user drags over the background + releases, this counts as a click event - it shouldn't
	lets use mousedown/mouseup to detect if its a true click
	if mouseup is detected without mousedown, its not a click
	*/
	
	//$('.moverlay').css('cursor','pointer'); // ios make object clickable
	$(document).on(clickEventType, '.moverlay.open:not(#signin-overlay):not(#cart-added-overlay):not(#terms-overlay)', function(e) {
		if ($(e.target).hasClass("moverlay")) {
			if (preventClick) {
				return;
			}
			var thisOverlay = $(this).attr("id").substr(0,$(this).attr("id").indexOf("-"));
			toggleOverlay(thisOverlay+"-link",thisOverlay+"-overlay");
			//reset
			preventClick = false;
			isMouseDown = false;
		}
	});

	$(document).on("mousedown", '.moverlay.open:not(#signin-overlay):not(#cart-added-overlay):not(#terms-overlay)', function(e) {
		if ($(e.target).hasClass("moverlay")) {
			isMouseDown = true;
		}
	});
	$(document).on("mouseup", '.moverlay.open:not(#signin-overlay):not(#cart-added-overlay):not(#terms-overlay)', function(e) {
		if ($(e.target).hasClass("moverlay")) {
			preventClick = false;
			if (!isMouseDown) {
				preventClick = true;
			}
		}
	});

	$(".btn-signup").on("click", function(e){
		e.preventDefault();
		//signupWizard('next','');

		// signup state - go back to last stored page
		if ($(this).attr("id") == "btn-createaccount" && typeof(Storage) !== "undefined" && sessionStorage.lastStepActive != undefined) {

				if ($("#order-container").length == 0) { // no order page exists
				
					if (sessionStorage.lastStepActive < 4) {
						
						signupWizard('',sessionStorage.lastStepActive);
						
						if ($("#profile-otp-cell").attr("data-val") != "") {
							$("#profile-otp-request").addClass("hide");
							$("#profile-otp-success .msg").html("Your cell number "+formatCellNumber($("#profile-otp-cell").attr("data-val"))+" has been verified");
							$("#profile-otp-success").removeClass("hide");
						}
						
					} else if (sessionStorage.lastStepActive == 4) { // if on checkout in session, resubmit previous address form

						// step 3 fields completed				
						if ($("#profileAddress :input").filter(function(index, element) {return $(element).val() != "";}).serialize().split("&").length == 5) {
							//signupWizard('',3);
							//$("#btn-signup-3").submit();
							
							signupWizard('',3);
							$('#signup-3').addClass("active").afterTime(1000, function () {
								$("#btn-signup-3").submit();
							});
							
							
						} else { // step 3 not completed
							signupWizard('next','');
						}
					} else {
						signupWizard('next','');	
					}
				
				} else if ($("#order-container").length == 1) { // order page exists

					//signupWizard('',sessionStorage.lastStepActive);
					
					//signupWizard('',3);
					//$("#btn-signup-3").submit();
					
					signupWizard('',3);
					$('#signup-3').addClass("active").afterTime(1000, function () {
						$("#btn-signup-3").submit();
					});
					
				} else {
					signupWizard('next','');
				}

		} else {
			signupWizard('next','');
		}
		
	});

	
