$("#idNumber").on("keyup change", function() {
	if ( $("#tempUser").data('formValidation').isValidField('idNumber') ) {
		setDob($(this).val(),"profileDob");
	} else {
		$("#profileDob").val("");
	}
});



function setDob(idNumber,idSelector) {
	const yy = parseInt(idNumber.substring(0, 2), 10);
	const mm = idNumber.substring(2, 4);
	const dd = idNumber.substring(4, 6);

	// Determine century logically
	const currentYear = new Date().getFullYear();
	const currentCentury = Math.floor(currentYear / 100); // e.g., 20 for 2025
	const currentYearTwoDigits = currentYear % 100;

	const fullYear = yy <= currentYearTwoDigits
		? (currentCentury * 100 + yy)   // e.g., 2000–2025
		: ((currentCentury - 1) * 100 + yy); // e.g., 1926–1999

	const formattedDate = `${fullYear}-${mm}-${dd}`;

	$("#"+idSelector).val(formattedDate);
}


function getDoB1(idNumber) {
	var Year = idNumber.substring(0, 2);
	var Month = idNumber.substring(2, 4);
	var Day = idNumber.substring(4, 6);
	var createDate = new Date(Year, Month-1, Day);
	var startDate = createDate.getFullYear() + "-" + Month + "-" + Day;
	$("#dateOfBirth").val(startDate);
}


var iniTimerStart = false;
var requestOtpTimeout;

function iniProfileTimer() {
	
	if (!iniTimerStart) {
		// only initialize once
		$("#profile-ms-timer").countdowntimer({
			minutes : 2,
			seconds : 59,
			timeUp : profileTimerComplete,
			displayFormat : "MS",
			beforeExpiryTime : "00:00:00:30",
			beforeExpiryTimeFunction : profileBeforeExpiry
		});
		iniTimerStart = true;
	} else {
		// restart timer
		$("#profile-ms-timer").countdowntimer("stop", "stop");
		$("#profile-ms-timer").countdowntimer("stop", "start"); 
	}
	
}


function startProfileTimer() {
	stopProfileTimer();
	$("#profile-time-remaining").removeClass("hide");
	iniProfileTimer();
	
	requestOtpTimeout = setTimeout(() => {
		$("#wrapper-otp-request-another").removeClass("hide");
	}, 60000);
	$("#wrapper-otp-request-another").addClass("hide");
}

function profileBeforeExpiry() {
	$("#profile-ms-timer").addClass("profile-otp-warn");
}

function stopProfileTimer() {
	$("#profile-ms-timer").removeClass("profile-otp-warn");
	$("#profile-time-remaining").addClass("hide");
	//$("#profile-ms-timer").countdowntimer("destroy");
	
	if (iniTimerStart) {
		$("#profile-ms-timer").countdowntimer("stop", "stop");
	}
	
	clearTimeout(requestOtpTimeout);
}

function profileTimerComplete() {
	$("#profile-time-remaining").addClass("hide");
	$("#profile-otp-request .errmsg").removeClass("hide").html("OTP Timeout. Please re-enter your cell number &amp; request another OTP.");
	$("#profile-otp-verify .msg").html("").addClass("hide");
	$("#profile-otp-verify").addClass("hide");
	$("#profile-otp-request").removeClass("hide");
	$("#frm-profile-otp-request").data("formValidation").resetForm();
}

function requestAnotherProfileOTP() {
	stopProfileTimer();
	$("#profile-otp-request .errmsg").removeClass("hide").html("");
	$("#profile-otp-verify .msg").html("").addClass("hide");
	$("#profile-otp-success").addClass("hide");
	$("#profile-otp-verify").addClass("hide");
	$("#profile-otp-request").removeClass("hide");
	$("#frm-profile-otp-request").data("formValidation").resetForm();
	$("#profile-otp-cell").focus();
}

$("#btn-otp-request-another").on(clickEventType, function(e) {
	requestAnotherProfileOTP();
});

$("#btn-otp-request-anotherone").on(clickEventType, function(e) {
	requestAnotherProfileOTP();
});

$("#btn-otp-success").on(clickEventType, function(e) {
	signupWizard('',3);
});

function formatCellNumber(number) {
    return number.replace(/^(\d{3})(\d{3})(\d{4})$/, "$1 $2 $3");
}

function requestProfileOTPPin(frm) {
	//console.log('request');
	$(".product-loader").remove();
	$("#profile-otp-request").prepend('<div class="product-loader"><i class="fa fa-refresh fa-spin"></i></div>');

	if ( typeof(reqOTPAjax) == "object" ) { // prevent multiple calls
		reqOTPAjax.abort();
	}

	reqOTPAjax = $.ajax({
		method: "POST",
		url: "/user/send-contact-verification-otp-ajax",
		timeout: 25000,
		cache: false,
		data: frm.serialize(),
		dataType: "json"
	})
	.done(function(data) {
		$(".product-loader").remove();
		frm.find(".errmsg").addClass("hide");
		//console.log(data);
		
		if (data.success == 1) {
			$("#profile-otp-request").addClass("hide");
			//$("#profile-otp-number").html($("#profile-otp-cell").val());
			$("#profile-otp-verify .errmsg").html("").addClass("hide");
			$("#profile-otp-verify .msg").html("Sent to "+formatCellNumber($("#profile-otp-cell").val())).removeClass("hide");
			
			$("#profile-otp-verify").removeClass("hide");
			$("#profile-otp-pin").val("").focus();
			startProfileTimer();
		} else if (data.success == 0) {
			$("#signup-4 .moverlay-content").velocity("callout.shake");
			frm.find(".errmsg").html(data.message).removeClass("hide");
		} else if (data.success == 2) {
			alert("OTP Verification is currently unavailable. Please continue with the sign-up process.");
			$("#profile-otp-request").addClass("hide");
			$("#profile-otp-success .msg").html("Your cell number "+formatCellNumber($("#profile-otp-cell").attr("data-val"))+" has been saved");
			$("#profile-otp-success").removeClass("hide")			
			signupWizard('',3);
		}
	})
	.fail(function() {
		console.log("error on OTP request");
		$(".product-loader").remove();
		frm.find(".errmsg").addClass("hide");
		frm.data("formValidation").resetForm();
	});
}

function setContactCell(frm) {

	$(".product-loader").remove();
	$("#profile-otp-request").prepend('<div class="product-loader"><i class="fa fa-refresh fa-spin"></i></div>');

	if ( typeof(setCellAjax) == "object" ) { // prevent multiple calls
		setCellAjax.abort();
	}

	setCellAjax = $.ajax({
		method: "POST",
		url: " /user/bypass-verify-contact-otp-ajax",
		timeout: 25000,
		cache: false,
		data: frm.serialize(),
		dataType: "json"
	})
	.done(function(data) {
		$(".product-loader").remove();
		frm.find(".errmsg").addClass("hide");
		//console.log(data);
		
		if (data.success == 1) {
			$("#profile-otp-request").addClass("hide");
			$("#profile-otp-success .msg").html("Your cell number "+formatCellNumber($("#profile-otp-cell").attr("data-val"))+" has been saved");
			$("#profile-otp-success").removeClass("hide");
			signupWizard('',3);
		} else {
			$("#signup-4 .moverlay-content").velocity("callout.shake");
			frm.find(".errmsg").html(data.message).removeClass("hide");
		}
	})
	.fail(function() {
		console.log("error on setting cell number");
		$(".product-loader").remove();
		frm.find(".errmsg").addClass("hide");
		frm.data("formValidation").resetForm();
	});
}


$("#frm-profile-otp-request").formValidation({
	framework: "bootstrap",
	excluded: ":disabled",
	icon: {
		valid:"icon-yes",
		invalid: "icon-no",
		validating: "fa fa-refresh"
	},
	fields: {
		cell: {
			validators: {
				notEmpty: {
					message: "Cell Number is a Required Field"
				},
				regexp: {
					regexp: /^(?=\d{10}$)(06|07|08)\d+/,
					message: "Your cell number must be 10 digits"
				}
			}
		}
	}
	})
	.on("success.form.fv", function(e) { 
		// Prevent form submission
		e.preventDefault();

		// Get the form instance
		var $form = $(e.target);
		var thisBypass = $("#frm-profile-otp-request").attr("data-switch");
		
		if (thisBypass == "1") {
			setContactCell($form);
		} else {
			requestProfileOTPPin($form);
		}
		
});

function verifyProfileOTPPin(frm) {
	$(".product-loader").remove();
	$("#profile-otp-verify").prepend('<div class="product-loader"><i class="fa fa-refresh fa-spin"></i></div>');

	if ( typeof(reqOTPAjax) == "object" ) { // prevent multiple calls
		reqOTPAjax.abort();
	}

	reqOTPAjax = $.ajax({
		method: "POST",
		url: "/user/verify-contact-otp-ajax",
		timeout: 25000,
		cache: false,
		data: frm.serialize(),
		dataType: "json"
	})
	.done(function(data) {
		$(".product-loader").remove();
		frm.find(".errmsg").addClass("hide");

		if (data.success == 1) {
			stopProfileTimer();
			//requestAnotherProfileOTP();
			$("#profile-otp-verify").addClass("hide");
			$("#profile-otp-success").removeClass("hide");
			$("#profile-otp-success .msg").html("Your cell number "+formatCellNumber(data.cell)+" has been verified");
			signupWizard('',3);
		} else if (data.success == 0) {
			$("#signup-2 .moverlay-content").velocity("callout.shake");
			frm.find(".errmsg").html(data.message).removeClass("hide");
		}
	})
	.fail(function() {
		console.log("error on Profile OTP verification");
		$(".product-loader").remove();
		frm.find(".errmsg").addClass("hide");
		frm.data("formValidation").resetForm();
	});
}

$("#frm-profile-otp-verify").formValidation({
	framework: "bootstrap",
	excluded: ":disabled",
	icon: {
		valid: "icon-yes",
		invalid: "icon-no",
		validating: "fa fa-refresh"
	},
	fields: {
		pin: {
			validators: {
				notEmpty: {
					message: "An OTP is required"
				}
			}
		}
	}
})
.on("success.form.fv", function(e) {

	// Prevent form submission
	e.preventDefault();

	// Get the form instance
	var $form = $(e.target);

	verifyProfileOTPPin($form);
});
